const s=wb.getWorksheet('Data');
s.getRange('AD14:AO42').setComputedValues; 
const cols=['AD','AE','AF','AG','AH','AI','AJ','AK','AL','AM','AN','AO'];
for(let r=14;r<=42;r++) for(const c of cols){
 s.getRange(c+r).setValue(`=IF(AND($L${r}<=${c}$9,ISNUMBER($J${r})),$W${r}*(1+$M${r})*(1+IF(EDATE($L${r},$J${r})<=${c}$9,$N${r},0))*(1+IF(EDATE($L${r},2*$J${r})<=${c}$9,$O${r},0))*(1+IF(EDATE($L${r},3*$J${r})<=${c}$9,$P${r},0)),"")`);
}
s.getRange('AD14').getStyle().update({fill:{type:'none'}});
log(s.getRegions('fill'));
log(s.getRegions('numberFormat').toString().slice(0,0));
log(s.getRange('AD14').getCell());
log(s.getRange('AO42').getCell());
s.getRange('AB9:AQ42')

